  if (typeof window.I18N === "object" && window.I18N) {
    Object.keys(RT_UI_I18N).forEach(function (lang) {
      if (window.I18N[lang]) {
        Object.assign(window.I18N[lang], RT_UI_I18N[lang]);
      }
    });
  }

  let currentData = window.HUDU_REALTIME_FALLBACK || null;
  let selectedProvinceCode = "ALL";
  let currentFeedFilter = "ALL";
  let toastIndex = 0;
  let toastDismissed = false;
  let toastTimer = null;

  function getLang() {
    const lang = document.documentElement.lang || "vi";
    return RT_UI_I18N[lang] ? lang : "vi";
  }

  function t(key) {
    const lang = getLang();
    return (RT_UI_I18N[lang] && RT_UI_I18N[lang][key]) || RT_UI_I18N.vi[key] || key;
  }

  function tBidForm(code, fallbackVi) {
    const lang = getLang();
    if (BID_FORM_I18N[code] && BID_FORM_I18N[code][lang]) {
      return BID_FORM_I18N[code][lang];
    }
    return fallbackVi || code;
  }

  function tDomain(code, fallbackVi) {
    const lang = getLang();
    if (DOMAIN_I18N[code] && DOMAIN_I18N[code][lang]) {
      return DOMAIN_I18N[code][lang];
    }
    return fallbackVi || code;
  }

  function tRegion(code) {
    const lang = getLang();
    if (REGION_I18N[code] && REGION_I18N[code][lang]) {
      return REGION_I18N[code][lang];
    }
    return code || "";
  }

  function fmtNum(n) {
    const num = Number(n) || 0;
    const lang = getLang();
    return num.toLocaleString(lang === "vi" || lang === "es" ? "vi-VN" : "en-US");
  }

  function fmtVndShort(vnd) {
    const val = Number(vnd) || 0;
    const lang = getLang();
    if (val >= 1e9) {
      const ty = (val / 1e9).toFixed(1).replace(/\.0$/, "");
      if (lang === "vi") return ty.replace(".", ",") + " Tỷ đ";
      if (lang === "zh") return ty + " 十亿盾";
      if (lang === "ja") return ty + " B VND";
      if (lang === "ko") return ty + " 십억 동";
      return ty + "B VND";
    }
    if (val >= 1e6) {
      const tr = Math.round(val / 1e6);
      return lang === "vi" ? tr + " Triệu đ" : tr + "M VND";
    }
    return fmtNum(val) + " ₫";
  }

  // Create SVG Pie or Donut paths
  function buildPieSvgContent(slices, cx, cy, rOuter, rInner, centerTopText, centerSubText) {
    const valid = (slices || []).filter(function (s) { return (Number(s.count) || 0) > 0; });
    const total = valid.reduce(function (acc, s) { return acc + (Number(s.count) || 0); }, 0);
    if (total <= 0) {
      return '<circle cx="' + cx + '" cy="' + cy + '" r="' + rOuter + '" fill="#CBD5E1" />';
    }

    let angleStart = -Math.PI / 2;
    const paths = [];

    valid.forEach(function (s) {
      const count = Number(s.count) || 0;
      const ratio = count / total;
      const sweep = ratio * Math.PI * 2;
      const angleEnd = angleStart + sweep;
      const color = s.color_hex || "#0077CC";
      const label = s.domain_label ? s.domain_label : tBidForm(s.code, s.label_vi);
      const pct = (ratio * 100).toFixed(2);

      if (ratio >= 0.9999) {
        paths.push(
          '<circle class="pie-slice" cx="' + cx + '" cy="' + cy + '" r="' + rOuter + '" fill="' + color + '" ' +
          'data-slice-label="' + escapeAttr(label) + '" data-slice-count="' + count + '" data-slice-pct="' + pct + '" />'
        );
      } else {
        const x1 = cx + rOuter * Math.cos(angleStart);
        const y1 = cy + rOuter * Math.sin(angleStart);
        const x2 = cx + rOuter * Math.cos(angleEnd);
        const y2 = cy + rOuter * Math.sin(angleEnd);
        const largeArc = sweep > Math.PI ? 1 : 0;

        let d = "";
        if (rInner > 0) {
          const ix1 = cx + rInner * Math.cos(angleEnd);
          const iy1 = cy + rInner * Math.sin(angleEnd);
          const ix2 = cx + rInner * Math.cos(angleStart);
          const iy2 = cy + rInner * Math.sin(angleStart);
          d = [
            "M", x1.toFixed(2), y1.toFixed(2),
            "A", rOuter, rOuter, 0, largeArc, 1, x2.toFixed(2), y2.toFixed(2),
            "L", ix1.toFixed(2), iy1.toFixed(2),
            "A", rInner, rInner, 0, largeArc, 0, ix2.toFixed(2), iy2.toFixed(2),
            "Z"
          ].join(" ");
        } else {
          d = [
            "M", cx, cy,
            "L", x1.toFixed(2), y1.toFixed(2),
            "A", rOuter, rOuter, 0, largeArc, 1, x2.toFixed(2), y2.toFixed(2),
            "Z"
          ].join(" ");
        }

        paths.push(
          '<path class="pie-slice" d="' + d + '" fill="' + color + '" ' +
          'data-slice-label="' + escapeAttr(label) + '" data-slice-count="' + count + '" data-slice-pct="' + pct + '" />'
        );
      }
      angleStart = angleEnd;
    });

    if (rInner > 0 && centerTopText) {
      paths.push(
        '<text x="' + cx + '" y="' + (cy - 3) + '" text-anchor="middle" style="font-size:15px;font-weight:800;fill:var(--text-heading);">' +
          escapeHtml(centerTopText) +
        '</text>' +
        '<text x="' + cx + '" y="' + (cy + 14) + '" text-anchor="middle" style="font-size:9.5px;font-weight:700;fill:var(--text-muted);">' +
          escapeHtml(centerSubText || "") +
        '</text>'
      );
    }

    return paths.join("");
  }

  function escapeHtml(str) {
    return String(str || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function escapeAttr(str) {
    return escapeHtml(str).replace(/'/g, "&#39;");
  }

  // Render Vietnam SVG Map
  function renderVietnamMap(data) {
    const group = document.getElementById("rtVietnamPathsGroup");
    if (!group || !window.HUDU_VN_MAP_SHAPES) return;

    const provMap = {};
    (data.map_provinces || []).forEach(function (p) {
      provMap[p.province_code] = p;
    });

    const htmlParts = [];
    Object.keys(window.HUDU_VN_MAP_SHAPES).forEach(function (code) {
      const shape = window.HUDU_VN_MAP_SHAPES[code];
      const pData = provMap[code] || {};
      // Highlight VN-49 (Quang Nam) alongside VN-48 (Da Nang) in red so the Central region matches the reference visual
      let fill = pData.map_fill_color_hex || "#0077CC";
      if (code === "VN-49" || code === "VN-HS" || code === "VN-TS") {
        fill = "#E11D48";
      }
      const isSelected = selectedProvinceCode === code ? " active-prov" : "";
      htmlParts.push(
        '<path class="vn-prov' + isSelected + '" id="vnProv_' + code + '" data-prov-code="' + code + '" ' +
        'd="' + shape.d + '" fill="' + fill + '" />'
      );
    });

    group.innerHTML = htmlParts.join("");

    // Attach hover & click events
    group.querySelectorAll("path.vn-prov").forEach(function (pathEl) {
      const code = pathEl.getAttribute("data-prov-code");
      pathEl.addEventListener("mouseenter", function (ev) {
        showProvinceTooltip(code, ev);
      });
      pathEl.addEventListener("mousemove", function (ev) {
        moveTooltip(ev);
      });
      pathEl.addEventListener("mouseleave", function () {
        hideTooltip();
      });
      pathEl.addEventListener("click", function () {
        window.selectMapProvince(code);
      });
    });
  }

  // Render the 3 Featured Hub Pie Cards (Hà Nội, Đà Nẵng, TP. Hồ Chí Minh)
  function renderFeaturedHubs(data) {
    const hubs = data.featured_hubs || [];
    hubs.slice(0, 3).forEach(function (hub, idx) {
      const titleEl = document.getElementById("rtHubTitle" + idx);
      const metaEl = document.getElementById("rtHubMeta" + idx);
      const pieEl = document.getElementById("rtHubPie" + idx);
      const legEl = document.getElementById("rtHubLegend" + idx);
      if (!titleEl || !pieEl || !legEl) return;

      titleEl.textContent = hub.province_name;
      metaEl.textContent = fmtNum(hub.total_tenders) + " " + t("pkg_unit") + " · " + fmtNum(hub.open_tenders_count) + " " + t("open_unit");

      const slices = hub.bid_form_pie_chart || [];
      pieEl.innerHTML = buildPieSvgContent(slices, 80, 80, 74, 0);

      // Attach slice tooltip listeners
      bindPieSliceTooltips(pieEl, hub.province_name);

      const legHtml = slices
        .filter(function (s) { return (Number(s.count) || 0) > 0; })
        .map(function (s) {
          const lbl = tBidForm(s.code, s.label_vi);
          return (
            '<div class="rt-legend-item">' +
              '<div class="rt-legend-left">' +
                '<span class="rt-legend-dot" style="background:' + (s.color_hex || "#0077CC") + ';"></span>' +
                '<span>' + escapeHtml(lbl) + '</span>' +
              '</div>' +
              '<span class="rt-legend-val">' + Number(s.percentage).toFixed(1) + '%</span>' +
            '</div>'
          );
        })
        .join("");

      legEl.innerHTML = legHtml;
    });
  }

  // Render Top KPI Cards & Status Bar
  function renderTopKpis(data) {
    const totalEl = document.getElementById("rtKpiTotal");
    const openEl = document.getElementById("rtKpiOpen");
    const budgetEl = document.getElementById("rtKpiBudget");
    const topFormEl = document.getElementById("rtKpiTopForm");
    const topFormSubEl = document.getElementById("rtKpiTopFormSub");
    const tsEl = document.getElementById("rtUpdatedTimestamp");
    const winEl = document.getElementById("rtWindowInfo");

    if (totalEl) totalEl.textContent = fmtNum(data.national_total_tenders || 61089);

    const sumProvinceOpen = (data.map_provinces || []).reduce(function (acc, p) {
      return acc + (Number(p.open_tenders_count) || 0);
    }, 0);
    if (openEl) {
      openEl.textContent = fmtNum(sumProvinceOpen > 0 ? sumProvinceOpen : (data.national_open_tenders_count || 32));
    }

    if (budgetEl) {
      budgetEl.textContent = fmtVndShort(data.national_open_budget_vnd || 1023333535171);
    }

    const natPie = (data.national_bid_form_pie_chart || []).slice().sort(function (a, b) {
      return (Number(b.count) || 0) - (Number(a.count) || 0);
    });
    if (natPie.length > 0 && topFormEl && topFormSubEl) {
      const top = natPie[0];
      topFormEl.textContent = Number(top.percentage).toFixed(2).replace(".", ",") + "%";
      topFormSubEl.textContent = tBidForm(top.code, top.label_vi) + " (" + fmtNum(top.count) + " " + t("pkg_unit") + ")";
    }

    if (winEl) {
      winEl.textContent = t("window_fmt");
    }

    if (tsEl && data.generated_at) {
      try {
        const d = new Date(data.generated_at);
        tsEl.textContent = "Updated: " + d.toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
      } catch (e) {}
    }
  }

